fs::write(dest.join("README.md"),md).unwrap();for f in["analysis.json","probe.rs","legacy.rs","setup.rs","design.md","plan.json","pins.json","report.rs"]{fs::copy(r(f),artifacts.join(f)).unwrap();}fn collect(root:&Path,dir:&Path,out:&mut BTreeMap<String,String>){for e in fs::read_dir(dir).unwrap(){let p=e.unwrap().path();if p.is_dir(){collect(root,&p,out)}else{out.insert(p.strip_prefix(root).unwrap().display().to_string(),fs::read_to_string(p).unwrap());}}}let mut receipts=BTreeMap::new();collect(Path::new(R),&r("runs"),&mut receipts);let bytes=serde_json::to_vec(&receipts).unwrap();fs::write(r("receipts.json"),&bytes).unwrap();let gz=Command::new("gzip").args(["-n","-c"]).arg(r("receipts.json")).output().unwrap();assert!(gz.status.success());let p=artifacts.join("receipts.json.gz");fs::write(&p,gz.stdout).unwrap();let back=Command::new("gzip").arg("-dc").arg(p).output().unwrap();assert!(back.status.success());assert_eq!(back.stdout,bytes);let mut local=BTreeMap::new();for f in["tests","probe","setup"]{local.insert(f,hash(r(f)));}fs::write(artifacts.join("local-payload-sha256.json"),serde_json::to_vec_pretty(&local).unwrap()).unwrap();let mut files=vec![dest.join("README.md")];files.extend(fs::read_dir(&artifacts).unwrap().map(|e|e.unwrap().path()));files.sort();fs::write(dest.join("SHA256SUMS"),files.iter().map(|p|format!("{}  {}\n",hash(p),p.strip_prefix(dest).unwrap().display())).collect::<String>()).unwrap();println!("Count/metadata gate true;9fixtures18queries;{}pins;{}receiptmembers exact roundtrip;{}reportfiles; no newtimings/proofs",pins.as_object().unwrap().len(),receipts.len(),files.len()+1);
